// Symmetry.

let seed;
let mySize, margin;
let num;
let myGraphic;
let palette;
let str_wei;

let unit_x, unit_y;
let count;
let t;
let mods = [];
let a, b, c;

function setup() {
	a = TAU / TAU;
	b = a + a;
	c = a - a;
	seed = Math.random() * sq(sq(sq(int(TAU))));
	randomSeed(seed);

	mySize = max(windowWidth, windowHeight)*0.9;
	createCanvas(mySize, mySize, WEBGL);

	perspective(0.5, width / height, 5, 10000);
	palette = random(colorScheme).colors.concat();
	background(random(bgcolor));
	frameRate(50);
	t = rez = c = n = c;
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	randomSeed(seed);
	background(random(bgcolor));

	push();
	translate(0, 0, -mySize * 2.5);
	rotateX(random(TAU));
	rotateY(random(TAU));
	rotateZ(random(TAU));

	switch (random([1, 2, 3])) {
		case 1:
			rotateX(random([-1, 1]) * (frameCount * speedMult) / 100);
			break;
		case 2:
			rotateY(random([-1, 1]) * (frameCount * speedMult) / 100);
			break;
		case 3:
			rotateZ(random([-1, 1]) * (frameCount * speedMult) / 100);
			break;
	}

	let cubeSize = mySize / (a + a / b) / 2.0;
	let plus = cubeSize / 5;

	for (let i = -cubeSize / b; i < cubeSize / b + plus; i += plus * a) {
		for (let j = -cubeSize / b; j < cubeSize / b + plus; j += plus * a) {
			for (let k = -cubeSize / b; k < cubeSize / b + plus; k += plus * a) {
				strokeCap(PROJECT);
				n = noise(i * rez + t, j * rez + t, k * rez + t) * random(1, 10);

				push();
				translate(i * n, j * n, k * n);
				rotateX(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				rotateY(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				rotateZ(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				// rotateX(random([-1, 1]) * (frameCount * speedMult) / 100);
				// rotateY(random([-1, 1]) * (frameCount * speedMult) / 100);
				// rotateZ(random([-1, 1]) * (frameCount * speedMult) / 100);
				let planeSize = mySize / random([4, 16, 32, 64]);
				push();
				translate(i, j, k);
				switch (random([1, 1, 2])) {
					case 1:
						noStroke();
						fill(random(palette));
						plane(planeSize);

						break;
					case 2:
						noFill();
						stroke(random(palette));
						strokeWeight(random(1, 2));
						line(-planeSize / 2, -planeSize / 2, planeSize / 2, -planeSize / 2);
						line(planeSize / 2, -planeSize / 2, planeSize / 2, planeSize / 2);
						line(planeSize / 2, planeSize / 2, -planeSize / 2, planeSize / 2);
						line(-planeSize / 2, planeSize / 2, -planeSize / 2, -planeSize / 2);
						break;
				}

				// plane(random(mySize/10, mySize/2000));
				// box(random(mySize / 500, mySize / 20));
				pop();

				let px = plus / random(a, int(TAU)) / b / sin(n);
				let py = plus / random(a, int(TAU)) / b / cos(n);
				let pz = plus / random(a, int(TAU)) / b / tan(n);
				push();
				noStroke();
				fill(random(palette));
				translate(px, py, pz);
				rotateX(random([-1, 1]) * (frameCount * speedMult) / 100);
				rotateY(random([-1, 1]) * (frameCount * speedMult) / 100);
				rotateZ(random([-1, 1]) * (frameCount * speedMult) / 100);
				// sphere(mySize / 200);
				pop();

				noFill();
				stroke(random(palette));
				strokeWeight(random(a, b) * 2 / random(1, 100));
				line(0, 0, 0, px, py, pz);

				pop();
			}
		}
	}
	pop();
	t += 0.1 / 10;
}


